import { readFile } from 'node:fs/promises';
import { pathToFileURL } from 'node:url';
import { performance } from 'node:perf_hooks';
import { createHash } from 'node:crypto';
const { renderParticipantToSink } = await import(pathToFileURL(process.argv[2]));
const data = JSON.parse(await readFile(new URL('./data.json', import.meta.url), 'utf8'));
let html = '';
function write(value) { html += value; }
process.on('message', ({ iterations }) => {
	const started = performance.now();
	let bytes;
	for (let index = 0; index < iterations; index++) {
		html = '';
		bytes = renderParticipantToSink(data, '/incidents/inc-101', write, Buffer.byteLength);
	}
	const elapsedMs = performance.now() - started;
	const hash = createHash('sha256').update(html).digest('hex');
	process.send({ elapsedMs, iterations, bytes, hash });
});
process.send({ ready: true });

